import axios from 'axios';
import authService from './authService';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000/api';

// Helper function to get auth header
const authHeader = () => {
    const user = authService.getCurrentUser();
    if (user && user.token) {
        return { Authorization: `Bearer ${user.token}` };
    }
    return {};
};

// Stock Operations
export const getAllStocks = async () => {
    try {
        const response = await axios.get(`${API_URL}/store3/stocks`, { headers: authHeader() });
        return response.data;
    } catch (error) {
        throw error.response?.data || error.message;
    }
};

export const createStock = async (stockData) => {
    try {
        const response = await axios.post(`${API_URL}/store3/stocks`, stockData, { headers: authHeader() });
        return response.data;
    } catch (error) {
        throw error.response?.data || error.message;
    }
};

export const updateStock = async (stockData) => {
    try {
        const response = await axios.put(`${API_URL}/store3/stocks/${stockData.id}`, stockData, { headers: authHeader() });
        return response.data;
    } catch (error) {
        throw error.response?.data || error.message;
    }
};

export const deleteStock = async (id) => {
    try {
        const response = await axios.delete(`${API_URL}/store3/stocks/${id}`, { headers: authHeader() });
        return response.data;
    } catch (error) {
        throw error.response?.data || error.message;
    }
};

// Sale Operations
export const getAllSales = async () => {
    try {
        const response = await axios.get(`${API_URL}/store3/sales`, { headers: authHeader() });
        return response.data;
    } catch (error) {
        throw error.response?.data || error.message;
    }
};

export const createSale = async (saleData) => {
    try {
        const response = await axios.post(`${API_URL}/store3/sales`, saleData, { headers: authHeader() });
        return response.data;
    } catch (error) {
        throw error.response?.data || error.message;
    }
};

// Return Operations
export const getAllReturns = async () => {
    try {
        const response = await axios.get(`${API_URL}/store3/returns`, { headers: authHeader() });
        return response.data;
    } catch (error) {
        throw error.response?.data || error.message;
    }
};

export const createReturn = async (returnData) => {
    try {
        const response = await axios.post(`${API_URL}/store3/returns`, returnData, { headers: authHeader() });
        return response.data;
    } catch (error) {
        throw error.response?.data || error.message;
    }
};
